<template>
  <main class="admin-page">
    <header class="admin-toolbar"><div><p class="eyebrow">Administración</p><h1>{{ activeTab === 'products' ? 'Catálogo' : 'Galería' }} <em>editable.</em></h1></div><div class="toolbar-actions"><NuxtLink class="button button-ghost" to="/">Ver sitio</NuxtLink><button v-if="activeTab === 'products'" class="button button-primary" @click="startNew">Nuevo producto <Plus :size="16" /></button><button class="button button-ghost" @click="logout"><LogOut :size="16" /> Cerrar sesión</button></div></header>
    <nav class="admin-tabs"><button :class="{active:activeTab==='products'}" @click="activeTab='products'"><Package :size="16" /> Productos</button><button :class="{active:activeTab==='gallery'}" @click="activeTab='gallery'"><Images :size="16" /> Imágenes del inicio</button></nav>
    <Transition name="admin-view" mode="out-in">
      <section v-if="activeTab==='products'" key="products" class="admin-content"><div class="admin-list"><div class="list-heading"><p class="eyebrow">Productos cargados</p><strong>{{ productList.length }}</strong></div><p v-if="loadError" class="list-message error">No se pudo cargar la lista.</p><div v-for="product in productList" :key="product.slug" class="admin-product"><img :src="product.image" :alt="product.name" /><div><small>{{ product.code }} · {{ product.category }}</small><h2>{{ product.name }}</h2><p>{{ product.priceFrom ? `${format(product.priceFrom)} - ${format(product.priceTo)}` : 'A cotizar' }} + IVA</p></div><div class="row-actions"><button class="icon-button" @click="edit(product)"><Pencil :size="16" /></button><button class="icon-button danger" @click="remove(product.id)"><Trash2 :size="16" /></button></div></div></div><form class="admin-form" @submit.prevent="save"><p class="eyebrow">{{ editing?'Editar producto':'Nuevo producto' }}</p><label>Nombre<input v-model="form.name" required /></label><div class="form-grid"><label>Slug<input v-model="form.slug" required /></label><label>Código<input v-model="form.code" required /></label></div><label>Categoría<select v-model="form.category"><option>Racks metalicos</option><option>Estanterias metalicas</option><option>Gondolas</option><option>Soluciones especiales</option></select></label><div class="form-grid"><label>Precio desde<input v-model.number="form.priceFrom" type="number" min="0" /></label><label>Precio hasta<input v-model.number="form.priceTo" type="number" min="0" /></label></div><section class="image-manager"><div class="list-heading"><label>Imágenes del producto</label><span>{{ gallery.length }}/4</span></div><div class="image-grid"><article v-for="(image,index) in gallery" :key="image.id" class="image-card"><img :src="image.preview" /><label>Reemplazar<input type="file" accept="image/jpeg,image/png,image/webp" @change="replaceImage(index,$event)" /></label><button type="button" :disabled="gallery.length===1" @click="removeImage(index)">Quitar</button></article><label v-if="gallery.length<4" class="add-image">Agregar fotos<input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="addImages" /></label></div></section><label>Descripción técnica<textarea v-model="form.technicalDescription" rows="4" /></label><button class="button button-primary full-button" :disabled="saving">{{ saving?'Guardando...':'Guardar producto' }} <Save :size="16" /></button></form></section>
      <section v-else key="gallery" class="gallery-admin">
        <div v-if="galleryError" class="gallery-alert error"><span>!</span><div><strong>No pudimos cargar la galería</strong><small>Recargá la página para volver a intentarlo.</small></div></div>
        <div class="gallery-editor-layout">
          <div class="home-gallery-grid">
            <article v-for="(item,index) in homeGallery" :key="item.id" class="home-image-card" :class="{'is-featured':index===0}">
              <div class="home-image-preview"><img :src="item.preview" :alt="item.alt" /><div class="image-badges"><span>{{ String(index+1).padStart(2,'0') }}</span><span v-if="index===0" class="featured-badge">Destacada</span></div><label class="replace-image"><Upload :size="15" /> Cambiar imagen<input type="file" accept="image/jpeg,image/png,image/webp" @change="replaceHomeImage(index,$event)" /></label></div>
              <div class="home-image-fields"><label><span>Título <small>{{ item.title.length }}/60</small></span><input v-model="item.title" maxlength="60" placeholder="Título de la imagen" /></label><label><span>Descripción <small>{{ item.description.length }}/140</small></span><textarea v-model="item.description" maxlength="140" rows="3" placeholder="Contá brevemente qué muestra esta imagen" /></label></div>
            </article>
          </div>
        </div>
        <div class="gallery-save" :class="{'has-changes':galleryDirty}"><span class="save-status"><i><Check v-if="!galleryDirty" :size="11" /></i><span><strong>{{ galleryDirty?'Tenés cambios sin publicar':'Galería actualizada' }}</strong><small>{{ galleryDirty?'Guardá para verlos reflejados en el sitio.':'No hay cambios pendientes.' }}</small></span></span><div class="save-actions"><NuxtLink class="preview-link" to="/#galeria" target="_blank">Ver galería</NuxtLink><button class="button button-primary" :disabled="gallerySaving||!galleryDirty" @click="saveHomeGallery">{{ gallerySaving?'Publicando...':'Publicar cambios' }} <Save :size="16" /></button></div></div>
      </section>
    </Transition>
  </main>
</template>

<script setup lang="ts">
import { Check, Images, LogOut, Package, Pencil, Plus, Save, Trash2, Upload } from "lucide-vue-next";
import type { CatalogProduct } from "../../../data/products";
import { uploadProductImage } from "../../utils/cloudinary";
definePageMeta({ middleware: "admin" });
type ImageFile={id:string;preview:string;file?:File}; type HomeItem={id:string;preview:string;file?:File;title:string;description:string;alt:string;type:"image"|"video";position?:string;featured?:boolean};
const activeTab=ref<"products"|"gallery">("products"), productList=ref<CatalogProduct[]>([]), editing=ref(false), saving=ref(false), loadError=ref(false), gallery=ref<ImageFile[]>([]), originalId=ref<string|null>(null), homeGallery=ref<HomeItem[]>([]), gallerySaving=ref(false), galleryError=ref(false), savedGallerySnapshot=ref("");
const gallerySnapshot=()=>JSON.stringify(homeGallery.value.map(({id,preview,file,...item})=>({...item,src:preview})));
const galleryDirty=computed(()=>Boolean(savedGallerySnapshot.value)&&gallerySnapshot()!==savedGallerySnapshot.value);
const form=reactive<Partial<CatalogProduct>>({name:"",slug:"",code:"",category:"Racks metalicos",priceFrom:0,priceTo:0,technicalDescription:""}); const format=(value=0)=>`$ ${value.toLocaleString("es-AR")}`;
const toImage=(file:File):ImageFile=>({id:crypto.randomUUID(),preview:URL.createObjectURL(file),file});
async function load(){try{productList.value=await $fetch<CatalogProduct[]>("/api/admin/products");loadError.value=false}catch{loadError.value=true}}
async function loadHomeGallery(){try{const items=await $fetch<any[]>("/api/admin/gallery");homeGallery.value=items.map(item=>({...item,id:crypto.randomUUID(),preview:item.src}));savedGallerySnapshot.value=gallerySnapshot();galleryError.value=false}catch{galleryError.value=true}}
function edit(product:CatalogProduct){Object.assign(form,product);originalId.value=product.id || null;gallery.value=(product.images?.length?product.images:[product.image]).filter(Boolean).slice(0,4).map(preview=>({id:crypto.randomUUID(),preview}));editing.value=true}
function startNew(){Object.assign(form,{name:"",slug:"",code:"",category:"Racks metalicos",priceFrom:0,priceTo:0,technicalDescription:"",image:"",images:[]});originalId.value=null;gallery.value=[];editing.value=false}
function addImages(e:Event){const input=e.target as HTMLInputElement;gallery.value.push(...Array.from(input.files||[]).slice(0,4-gallery.value.length).map(toImage));input.value=""} function replaceImage(i:number,e:Event){const input=e.target as HTMLInputElement;if(input.files?.[0])gallery.value.splice(i,1,toImage(input.files[0]));input.value=""} function removeImage(i:number){if(gallery.value.length>1)gallery.value.splice(i,1)}
function replaceHomeImage(i:number,e:Event){const input=e.target as HTMLInputElement;if(input.files?.[0]){const item=homeGallery.value[i];item.file=input.files[0];item.preview=URL.createObjectURL(input.files[0]);item.type="image"}input.value=""}
async function save(){saving.value=true;try{const images=await Promise.all(gallery.value.map(i=>i.file?uploadProductImage(i.file):i.preview));const payload={...form,image:images[0],images,price:form.priceFrom||0};if(editing.value)await $fetch(`/api/admin/products/${encodeURIComponent(originalId.value||"")}`,{method:"PUT",body:payload});else await $fetch("/api/admin/products",{method:"POST",body:payload});await load();startNew()}finally{saving.value=false}}
async function saveHomeGallery(){gallerySaving.value=true;try{const items=await Promise.all(homeGallery.value.map(async({id,preview,file,...item},index)=>({...item,number:String(index+1).padStart(2,"0"),src:file?await uploadProductImage(file):preview})));await $fetch("/api/admin/gallery",{method:"PUT",body:{items}});await loadHomeGallery()}finally{gallerySaving.value=false}}
async function remove(id:string|undefined){if(confirm("¿Eliminar este producto?")){await $fetch(`/api/admin/products/${encodeURIComponent(id || "")}`,{method:"DELETE"});await load()}} async function logout(){await $fetch("/api/admin/logout",{method:"POST"});await navigateTo("/admin/login")} await Promise.all([load(),loadHomeGallery()]);
</script>

