/* Gallery editor */
.gallery-admin{max-width:1280px;margin:34px auto 110px}.gallery-alert{display:flex;align-items:center;gap:12px;margin-bottom:20px;padding:14px 16px;border:1px solid rgba(248,113,113,.35);background:rgba(220,38,38,.08)}.gallery-alert>span{display:grid;width:28px;height:28px;place-items:center;border-radius:50%;background:var(--red);color:#fff;font-weight:800}.gallery-alert div{display:grid;gap:3px}.gallery-alert small{color:var(--muted)}.gallery-editor-layout{display:block}.home-gallery-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.home-image-card,.home-image-card:first-child{display:flex;grid-row:auto;flex-direction:column;overflow:hidden;border:1px solid var(--line);background:var(--surface);transition:border-color .2s,transform .2s,box-shadow .2s}.home-image-card:hover{border-color:rgba(220,38,38,.6);transform:translateY(-2px);box-shadow:0 14px 35px rgba(0,0,0,.18)}.home-image-card.is-featured{grid-column:1/-1}.home-image-preview{position:relative;height:230px;overflow:hidden;background:#0b0c0e}.home-image-card.is-featured .home-image-preview{height:360px}.home-image-preview:after{position:absolute;inset:0;content:"";pointer-events:none;background:linear-gradient(180deg,rgba(0,0,0,.42),transparent 35%,rgba(0,0,0,.52))}.home-image-preview img,.home-image-card:first-child .home-image-preview img{width:100%;height:100%;object-fit:cover;transition:transform .35s}.home-image-card:hover .home-image-preview img{transform:scale(1.025)}.image-badges{position:absolute;z-index:1;top:14px;left:14px;display:flex;gap:7px}.image-badges span{padding:6px 8px;background:rgba(10,10,12,.78);backdrop-filter:blur(8px);color:#fff;font:10px "DM Mono"}.image-badges .featured-badge{background:var(--red);text-transform:uppercase}.replace-image{position:absolute;z-index:2;right:14px;bottom:14px;display:flex!important;grid-template:none!important;align-items:center;gap:7px!important;padding:9px 11px;border:1px solid rgba(255,255,255,.24);background:rgba(10,10,12,.8